module multi_16bit (
    input clk,
    input rst_n,
    input start,
    input [15:0] ain,
    input [15:0] bin,
    output [31:0] yout,
    output done
);

reg [31:0] product;
reg done_reg;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        product <= 0;
        done_reg <= 0;
    end else if (start) begin
        product <= ain * bin;
        done_reg <= 1;
    end else begin
        done_reg <= 0;
    end
end

assign yout = product;
assign done = done_reg;

endmodule
